"""Standalone job scraper for infosys.com (India roles). Generated by the agent; runs with NO LLM calls.
Run:  python scraper.py [output.jsonl]
source_type=html_ssr, pagination=page_number.
"""

import json
import os
import sys
import time
from datetime import datetime
from html import unescape
from urllib.parse import urljoin, urlparse, parse_qs, urlencode, urlunparse

import requests
from bs4 import BeautifulSoup

HEADERS = {
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
    "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
    "Accept-Language": "en-US,en;q=0.9",
}

BASE_URL = "https://career.infosys.com/joblist?companyhiringtype=BPM&countrycode=IN"


def parse_html(text):
    if isinstance(text, bytes):
        text = text.decode("utf-8", errors="replace")
    text = text or ""
    soup = BeautifulSoup(text, "lxml")
    for tag in ("input", "script", "a"):
        raw_count = text.count("<" + tag)
        if raw_count >= 2 and len(soup.find_all(tag)) < raw_count // 2:
            return BeautifulSoup(text, "html.parser")
    return soup


_INDIA_CITY_FALLBACK = {
    "bengaluru": "Bengaluru", "bangalore": "Bangalore", "mumbai": "Mumbai", "delhi": "Delhi",
    "new delhi": "New Delhi", "gurugram": "Gurugram", "gurgaon": "Gurgaon", "noida": "Noida",
    "hyderabad": "Hyderabad", "chennai": "Chennai", "pune": "Pune", "kolkata": "Kolkata",
    "ahmedabad": "Ahmedabad",
}


def resolve_location(location_raw):
    # returns (city, state, country, country_code) -- all None if unresolvable, never guessed.
    if not location_raw:
        return (None, None, None, None)
    first_segment = location_raw.split(";")[0].strip()  # some platforms join multiple locations with ';'
    parts = [p.strip() for p in first_segment.split(",")]
    if len(parts) >= 2:
        # explicit "City, [State,] Country" format -- last segment is the country
        city = parts[0] or None
        state = parts[1] if len(parts) >= 3 else None
        country_raw = parts[-1]
        if country_raw.lower() in ("india", "in"):
            return (city, state, "India", "IN")
        return (city, state, country_raw or None, None)
    # no comma: bare city name -- only resolve via the small generic fallback dict, never guess otherwise
    bare = first_segment.lower()
    if bare in _INDIA_CITY_FALLBACK:
        return (_INDIA_CITY_FALLBACK[bare], None, "India", "IN")
    return (None, None, None, None)


def parse_date_text(date_text):
    if not date_text:
        return None, None
    txt = date_text.strip()
    for fmt in ("%Y-%m-%d", "%d-%m-%Y", "%d/%m/%Y", "%b %d, %Y", "%B %d, %Y", "%d %b %Y", "%d %B %Y"):
        try:
            return datetime.strptime(txt, fmt).date().isoformat(), txt
        except Exception:
            pass
    try:
        return datetime.fromisoformat(txt).date().isoformat(), txt
    except Exception:
        return None, txt


def request_with_retries(session, url, params=None, timeout=30):
    last_status = None
    for attempt in range(4):
        try:
            resp = session.get(url, params=params, headers=HEADERS, timeout=timeout)
            last_status = resp.status_code
            if resp.status_code in (429, 500, 502, 503, 504, 403):
                if attempt < 3:
                    time.sleep(2 ** attempt)
                    continue
            return resp
        except requests.RequestException:
            if attempt < 3:
                time.sleep(2 ** attempt)
                continue
    return None


def normalize_url(base, maybe_url):
    if not maybe_url:
        return None
    return urljoin(base, maybe_url.strip())


def build_page_url(page_num):
    parsed = urlparse(BASE_URL)
    qs = parse_qs(parsed.query)
    qs["page"] = [str(page_num)]
    new_query = urlencode(qs, doseq=True)
    return urlunparse((parsed.scheme, parsed.netloc, parsed.path, parsed.params, new_query, parsed.fragment))


def extract_jobs_from_page(soup, page_url):
    jobs = []
    seen = set()

    candidates = soup.select("a[href]")
    for a in candidates:
        href = a.get("href")
        text = " ".join(x.strip() for x in a.stripped_strings)
        if not text:
            continue
        if "joblist" not in (href or "") and "career" not in (href or ""):
            continue
        title = text
        location_raw = None
        parent = a.parent
        if parent:
            parent_text = " ".join(x.strip() for x in parent.stripped_strings)
            if parent_text and parent_text != title:
                location_raw = parent_text
        job_url = normalize_url(page_url, href)
        dedupe_key = job_url or title
        if dedupe_key in seen:
            continue
        seen.add(dedupe_key)
        city, state, country, country_code = resolve_location(location_raw)
        if country_code != "IN" and country != "India":
            continue
        jobs.append({
            "title": title or None,
            "job_id": None,
            "location": {"city": city, "state": state, "country": country, "country_code": country_code},
            "url": job_url,
            "apply_url": None,
            "date_posted": None,
            "date_posted_text": None,
            "job_description": None,
            "employment_type": None,
            "work_type": None,
            "salary_range": None,
        })
    return jobs


def main():
    out_path = sys.argv[1] if len(sys.argv) > 1 else os.path.join(os.path.dirname(os.path.abspath(__file__)), "output.jsonl")
    session = requests.Session()
    all_jobs = []
    seen = set()
    try:
        page = 1
        while True:
            page_url = build_page_url(page)
            resp = request_with_retries(session, page_url)
            if resp is None:
                raise RuntimeError("request failed")
            if resp.status_code == 403:
                print(f"error: blocked with 403 on page {page}", file=sys.stderr)
                break
            if resp.status_code >= 400:
                raise RuntimeError(f"HTTP {resp.status_code} on page {page}")
            soup = parse_html(resp.text)
            jobs = extract_jobs_from_page(soup, page_url)
            if not jobs:
                break
            for job in jobs:
                key = job["url"] or job["job_id"] or job["title"]
                if key in seen:
                    continue
                seen.add(key)
                all_jobs.append(job)
            page += 1
            time.sleep(0.35)
    except Exception as e:
        try:
            with open(out_path, "w", encoding="utf-8") as f:
                for job in all_jobs:
                    f.write(json.dumps(job, ensure_ascii=False) + "\n")
        finally:
            print(f"error: {e}", file=sys.stderr)
            sys.exit(1)

    with open(out_path, "w", encoding="utf-8") as f:
        for job in all_jobs:
            f.write(json.dumps(job, ensure_ascii=False) + "\n")


if __name__ == "__main__":
    main()